def solve(n):
    """Return the number of prime numbers strictly less than n.
    Uses the Sieve of Eratosthenes. Handles n <= 2 and any non‑negative integer.
    """
    if n <= 2:
        return 0
    # Initialize sieve array where index i indicates primality of i.
    sieve = [True] * n
    sieve[0] = sieve[1] = False
    import math
    limit = int(math.isqrt(n - 1))
    for i in range(2, limit + 1):
        if sieve[i]:
            # Mark multiples of i starting from i*i.
            for j in range(i * i, n, i):
                sieve[j] = False
    return sum(sieve)

