from fractions import Fraction

def solve(matrix):
    # determinant of square matrix, empty => 1
    if not matrix:
        return 1
    n = len(matrix)
    # make a deep copy as Fractions
    A = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and A[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            sign *= -1
        piv_val = A[i][i]
        det *= piv_val
