{"task_id": "T25", "code": "def solve(matrix):
    """Determinant using Bareiss fraction-free algorithm.
    Returns integer determinant, empty matrix -> 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # copy to ints
    A = [row[:] for row in matrix]
    sign = 1
    prev = 1
    for k in range(n-1):
        # pivot handling: if zero, find row to swap
        if A[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            A[k], A[swap] = A[swap], A[k]
            sign *= -1
        pivot = A[k][k]
        for i in range(k+1, n):
            for j in range(k+1, n):
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // prev
        prev = pivot
    det = sign * A[n-1][n-1]
    return det"}

