def solve(path):
    """Simplify an absolute Unix file path.
    Resolves '.' and '..', removes extra slashes, and returns the canonical path.
    """
    # Split the path by '/' and process each component using a stack.
    stack = []
    for part in path.split('/'):
        if not part or part == '.':
            # Skip empty parts (caused by //) and current directory references.
            continue
        if part == '..':
            # Pop the last valid directory if any; otherwise stay at root.
            if stack:
                stack.pop()
        else:
            # Normal directory name.
            stack.append(part)
    # Reconstruct the simplified path.
    return '/' + '/'.join(stack) if stack else '/'

