def solve(mat):
    # Determinant using Bareiss algorithm (fraction-free Gaussian elimination).
    if not mat:
        return 1
    n = len(mat)
    for row in mat:
        if len(row)!=n:
            raise ValueError('Matrix must be square')
    a = [list(map(int,row)) for row in mat]
    det_sign = 1
    prev = 1
    for k in range(n-1):
        # Pivot handling
        if a[k][k] == 0:
            swap = None
            for i in range(k+1,n):
                if a[i][k] != 0:
                    swap = i; break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            det_sign = -det_sign
        pivot = a[k][k]
        for i in range(k+1,n):
            for j in range(k+1,n):
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return det_sign * a[n-1][n-1]

