def solve(matrix):
    """Compute determinant of a square integer matrix.
    Uses recursion for small matrices and Gaussian elimination with Fractions for larger ones.
    Empty matrix returns 1 as specified.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Validate square matrix; if not square, return 0
    for row in matrix:
        if len(row) != n:
            return 0
    # Recursive definition for small n (<=5) to avoid overhead and ensure correctness
    if n <= 5:
        def det_recursive(m):
            size = len(m)
            if size == 1:
                return m[0][0]
            if size == 2:
                return m[0][0]*m[1][1] - m[0][1]*m[1][0]
            total = 0
            for col in range(size):
                # build submatrix without first row and current column
                sub = [row[:col] + row[col+1:] for row in m[1:]]
                sign = -1 if col % 2 else 1
                total += sign * m[0][col] * det_recursive(sub)
            return total
        return det_recursive(matrix)
    # For larger matrices, use Gaussian elimination with exact rational arithmetic
    from fractions import Fraction
    A = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and A[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            sign *= -1
        piv_val = A[i][i]
        det *= piv_val
        for j in range(i+1, n):
            factor = A[j][i] / piv_val
            for k in range(i, n):
                A[j][k] -= factor * A[i][k]
    det *= sign
    # Result should be integral
    return int(det)

