def solve(grid):
    """Count the number of islands in a grid of 0/1 values.
    Handles empty grid, non-rectangular rows, and values that are int-like.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    count = 0
    for i in range(rows):
        cols = len(grid[i])
        for j in range(cols):
            if (i, j) in visited:
                continue
            # treat any truthy non-zero as land
            if grid[i][j]:
                count += 1
                # DFS stack
                stack = [(i, j)]
                visited.add((i, j))
                while stack:
                    x, y = stack.pop()
                    # neighbors: up, down, left, right
                    for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
