def solve(matrix):
    """Return the determinant of a square integer matrix (Bareiss algorithm)."""
    n = len(matrix)
    if n == 0:
        return 1
    M = [row[:] for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        pivot_row = None
        for r in range(k, n):
            if M[r][k] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0  # whole column zero -> singular
        if pivot_row != k:
            M[k], M[pivot_row] = M[pivot_row], M[k]
            sign = -sign
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                M[i][j] = (M[i][j] * M[k][k] - M[i][k] * M[k][j]) // prev
        prev = M[k][k]
    return sign * M[n - 1][n - 1]

